from heapq import heapify, heappop, heappush

from .model import load_group


def balances(group):
    members, expenses = load_group(group)
    net = dict.fromkeys(members, 0)
    for payer, amount, shares in expenses:
        net[payer] += amount
        for name, share in shares.items():
            net[name] -= share
    return net


def settle(group):
    net = balances(group)
    # Negative priorities put the largest amounts first, with names breaking ties.
    debtors = [(balance, name) for name, balance in net.items() if balance < 0]
    creditors = [(-balance, name) for name, balance in net.items() if balance > 0]
    heapify(debtors)
    heapify(creditors)

    transfers = []
    while debtors:
        debt, debtor = heappop(debtors)
        credit, creditor = heappop(creditors)
        payment = min(-debt, -credit)
        transfers.append((debtor, creditor, payment))
        if debt + payment < 0:
            heappush(debtors, (debt + payment, debtor))
        if credit + payment < 0:
            heappush(creditors, (credit + payment, creditor))
    return transfers

