        rate_text[currency.lower()] = decimal_text(numerator, places)
        precise_rates[currency] = Fraction(numerator, 10 ** places)
    expected = dict.fromkeys(members, 0)
    expenses = []
    for index in range(rng.randrange(1, 25)):
        amount = rng.choice([rng.randrange(1, 30), rng.randrange(1, 10 ** 45)])
        currency = rng.choice([*currencies, \"USD\"])
        payer = rng.choice(members)
        selected = rng.sample(members, rng.randrange(1, len(members) + 1))
        weights = {name: rng.choice([rng.randrange(1, 6), rng.randrange(1, 10 ** 100)]) for name in selected}
        split_type = rng.choice([\"equal\", \"shares\"])
        if split_type == \"equal\":
            split = {\"type\": \"equal\", \"among\": selected}
            weights = dict.fromkeys(selected, 1)
        else:
            split = {\"type\": \"shares\", \"shares\": weights}
        expenses.append({\"id\": str(index), \"currency\": currency.lower(), \"amount\": decimal_text(amount, 2),
                         \"payer\": payer, \"split\": split})
        converted = round(amount * precise_rates.get(currency, Fraction(1)))
        expected[payer] += converted
        for name, share in reference_shares(converted, weights).items():
            expected[name] -= share

    group = {\"currency\": \"uSd\", \"members\": members, \"rates\": rate_text, \"expenses\": expenses}
    assert sum(expected.values()) == 0
    assert ledger.balances(group) == expected, trial
    assert ledger.settle(group) == reference_settlement(expected), trial

